test("video keeps its decoded poster geometry while the player loads metadata", async ({ page }) => {
  await enterChat(page);
  await page.evaluate(async ({ account, device }) => {
    const canvas = document.createElement("canvas");
    canvas.width = 640; canvas.height = 360;
    canvas.getContext("2d")!.fillRect(0, 0, 640, 360);
    const stream = canvas.captureStream(30);
    const recorder = new MediaRecorder(stream, { mimeType: "video/webm" });
    const chunks: Blob[] = [];
    recorder.ondataavailable = event => chunks.push(event.data);
    const finished = new Promise<void>(resolve => { recorder.onstop = () => resolve(); });
    recorder.start();
    await new Promise(resolve => setTimeout(resolve, 150));
    recorder.stop(); await finished;
    stream.getTracks().forEach(track => track.stop());
    const bytes = await new Blob(chunks, { type: "video/webm" }).arrayBuffer();
    const win = window as unknown as { __TAURI_INTERNALS__: { invoke: (cmd: string, args: Record<string, unknown>) => Promise<unknown> } };
    const original = win.__TAURI_INTERNALS__.invoke;
    win.__TAURI_INTERNALS__.invoke = async (cmd, args) => {
      if (cmd === "read_media" && args.fileConv === "video-layout") return bytes;
      if (cmd === "file_statuses") return (args.fileConvs as string[]).map(file_conv => ({ file_conv, ready: true, done: 1, total: 1 }));
      const value = await original(cmd, args);
      if (cmd === "owner_account_history" && args.account === account) return [...value as unknown[], { id: "video-layout", from_me: false, who: device, text: "", wall_clock: Date.now(), reply_to: null, file: { file_conv: "video-layout", name: "clip.webm", size: bytes.byteLength, media: true, mime: "video/webm" } }];
      return value;
    };
  }, BOB);
  await openBobDm(page);
  await expect(page.getByTestId("file-video")).toHaveJSProperty("naturalWidth", 640);
  await page.evaluate(() => {
    const original = HTMLMediaElement.prototype.setAttribute;
    const held: Array<{ node: HTMLMediaElement; src: string }> = [];
    HTMLMediaElement.prototype.setAttribute = function(name, value) {
      if (name === "src" && this.tagName === "VIDEO") { held.push({ node: this, src: value }); return; }
      return original.call(this, name, value);
    };
    Object.assign(window, { __releasePlayer: () => { HTMLMediaElement.prototype.setAttribute = original; for (const { node, src } of held) original.call(node, "src", src); } });
  });
  await page.getByTestId("file-video").click();
  const player = page.getByTestId("file-video-player");
